function operations(full=false,overseas=false){const list=overseas?D.overseasPlatforms:D.platforms,stage=overseas?'platform-global':'platform-china';return '<section class="page operations-v9" id="'+(overseas?'chapter-overseas':'chapter-operations')+'">'+head('operations','运营战绩。<br><em>从内容，到生意。</em>',overseas?'海外运营 / 内容矩阵 / 推广获客 / 系统搭建':'国内运营 / 直播 / 矩阵 / 个人 IP',full)+'<div class="segmented region-tabs"><a class="'+(!overseas?'active':'')+'" href="#/operations">国内 · CHINA</a><a class="'+(overseas?'active':'')+'" href="#/operations/overseas">海外 · GLOBAL</a></div><div class="platform-universe"><div class="platform-intro">'+eyebrow('01 / PLATFORMS I WORK WITH')+'<h2>熟悉的平台，<br><em>各有打法。</em></h2><p>'+E(overseas?'熟悉 Instagram、Facebook、TikTok、YouTube，结合语言、受众和推广目标安排内容。':'熟悉八个国内内容平台，围绕平台特点组织选题、分发、直播与私域承接。')+'</p><div class="platform-icon-rail">'+list.map(x=>'<span>'+icon(x)+'<small>'+E(x)+'</small></span>').join('')+'</div><div class="platform-selection" id="'+stage+'-selection">'+icon(list[0])+'<span>'+E(list[0])+'</span><small>拖动球体 · 点选平台</small></div></div><div class="play-stage platform-stage" id="'+stage+'" data-platforms="'+(overseas?'global':'china')+'" tabindex="0" aria-label="可拖动的平台链路球"><canvas aria-hidden="true"></canvas><div class="orbit-items"></div><span class="platform-core">'+(overseas?'GLOBAL':'CHINA')+'<small>MY PLATFORM MAP</small></span></div></div>'+'<div id="'+stage+'-services"></div>'+st('02 / WHAT I DO','擅长的事，展开说。')+'<div class="service-grid">'+D.operationServices[overseas?'overseas':'domestic'].map((x,i)=>'<article><small>0'+(i+1)+' / '+E(x.english)+'</small><h3>'+E(x.name)+'</h3><p>'+E(x.lead)+'</p>'+tags(x.areas)+'<ol>'+x.steps.map(s=>'<li>'+E(s)+'</li>').join('')+'</ol></article>').join('')+'</div>'+'<div id="'+stage+'-results"></div>'+(overseas?overseasResults():domesticResults(full))+'</section>';}
