function renderTable(t,title='脚本表格'){
 if(!t.rows?.length)return '';const rows=t.rows.map(r=>r.map(c=>String(c??''))),headers=(t.headers||[]).map(String),n=Math.max(headers.length,...rows.map(r=>r.length));
 const merges=new Map(),covered=new Set();for(const m of t.merges||[]){if(!Array.isArray(m)||m.length!==4||!m.every(Number.isInteger))continue;const [r,c,re,ce]=m;if(r<0||c<0||re<r||ce<c||re>=rows.length||ce>=n)continue;merges.set(r+':'+c,{rowspan:re-r+1,colspan:ce-c+1});for(let y=r;y<=re;y++)for(let x=c;x<=ce;x++)if(y!==r||x!==c)covered.add(y+':'+x);}
 const heading=rows.findIndex(r=>r.some(v=>/^(镜号|镜头号|序号)$/.test(v.trim()))),labelRow=heading>=0?rows[heading]:headers;
 const widths=Array.from({length:n},(_,i)=>{const h=labelRow[i]||'';if(n===1)return 760;if(/画面|对白|台词|文案|内容|要求/.test(h))return 260;if(/^(镜号|镜头号|序号|时长)$/.test(h))return 76;return Math.max(80,Math.min(240,Math.round((t.columnWidths?.[i]||16)*7+14)));});
 const rowHTML=(r,y)=>{const isHeading=(t.headerRows||[]).includes(y)||y===heading;return '<tr'+(isHeading?' class="sheet-heading"':y===0&&r.filter(Boolean).length===1?' class="sheet-title"':'')+'>'+Array.from({length:n},(_,c)=>{if(covered.has(y+':'+c))return '';const m=merges.get(y+':'+c),tag=isHeading?'th':'td';return '<'+tag+(isHeading?' scope="col"':'')+(m?' rowspan="'+m.rowspan+'" colspan="'+m.colspan+'"':'')+'>'+E(r[c]||'')+'</'+tag+'>';}).join('')+'</tr>';};
 return '<div class="script-table-shell"><div class="sheet-toolbar"><span>原稿表格</span><small>'+n+' 列 · '+rows.length+' 行'+(n>3?' · 横向滚动查看全部列':'')+'</small></div><div class="table-scroll script-table workbook-table" tabindex="0" role="region" aria-label="'+E(title)+'，可横向滚动"><table style="width:'+Math.max(720,widths.reduce((a,b)=>a+b,0))+'px"><caption class="sr-only">'+E(title)+'</caption><colgroup>'+widths.map(w=>'<col style="width:'+w+'px">').join('')+'</colgroup>'+(headers.length?'<thead><tr>'+headers.map(h=>'<th scope="col">'+E(h)+'</th>').join('')+'</tr></thead>':'')+'<tbody>'+rows.map(rowHTML).join('')+'</tbody></table></div></div>';
}
