function watchViewerMedia(){
 const media=dialog.querySelector('img');if(!media)return;const body=document.querySelector('#viewer-body');
 const status=document.createElement('div');status.className='viewer-status';status.setAttribute('role','status');status.textContent='正在加载'+(media.tagName==='VIDEO'?'视频':'原图')+'…';body.append(status);
 const loaded=()=>{status.remove();media.classList.remove('media-failed');};
 const failed=()=>{media.classList.add('media-failed');status.classList.add('is-error');status.innerHTML='<strong>素材暂时没有加载成功</strong><p>请检查网络后重试。</p><button data-media-retry>重新加载</button>';};
 media.addEventListener('load',loaded,{once:true});media.addEventListener('loadeddata',loaded,{once:true});media.addEventListener('error',failed,{once:true});media.querySelector('source')?.addEventListener('error',failed,{once:true});
 if(media.tagName==='IMG'&&media.complete)(media.naturalWidth?loaded:failed)();else if(media.readyState>=2)loaded();
}

