 return '<svg class="libra-sculpture" viewBox="0 0 400 300" role="img" aria-label="天秤座，金色天秤与星轨"><defs><linearGradient id="'+id+'-gold" x1="0" x2="1" y2="1"><stop stop-color="#fff4ce"/><stop offset=".32" stop-color="#f1c675"/><stop offset=".55" stop-color="#9a672e"/><stop offset=".72" stop-color="#fff1bf"/><stop offset="1" stop-color="#c88c42"/></linearGradient><radialGradient id="'+id+'-light"><stop stop-color="#e7bd672d"/><stop offset="1" stop-color="#e7bd6700"/></radialGradient></defs><ellipse cx="200" cy="150" rx="175" ry="140" fill="url(#'+id+'-light)"/><g fill="none" stroke="#daba753b"><ellipse cx="200" cy="153" rx="165" ry="90" transform="rotate(-24 200 153)"/><circle cx="200" cy="147" r="116"/><path d="M44 80L101 42 274 54 347 214 260 253" stroke-dasharray="3 8"/></g><g fill="#ffe0a0"><circle cx="101" cy="42" r="3"/><circle cx="274" cy="54" r="3"/><circle cx="347" cy="214" r="3"/><path d="M55 182l3-8 3 8 8 3-8 3-3 8-3-8-8-3zM328 92l2-6 2 6 6 2-6 2-2 6-2-6-6-2z"/></g><ellipse cx="204" cy="264" rx="94" ry="12" fill="#0005"/><g fill="url(#'+id+'-gold)" stroke="#ffdf9b" stroke-width=".6"><path d="M194 80l12-5 7 169-20 7z"/><path d="M154 252l40-13h21l38 13 10 10H145z"/><path d="M87 105l116-36 113 40-4 10-109-34-112 31z"/><circle cx="203" cy="76" r="13"/></g><g fill="none" stroke="url(#'+id+'-gold)" stroke-width="2"><path d="M96 110L57 198H135zM308 115L270 204H347z"/></g><g fill="url(#'+id+'-gold)" stroke="#ffdf9b"><path d="M52 197h89q-5 35-44 35t-45-35zM264 203h89q-5 35-44 35t-45-35z"/></g><path d="M63 202h65M275 208h65" stroke="#fff2cf" stroke-width="2"/><text x="200" y="290" fill="#d8bd87" text-anchor="middle" font-size="8" letter-spacing="5">BALANCE / PERSPECTIVE / TASTE</text></svg>';
